/* ─── Sidebar ─────────────────────────────────────────────────────── */
function Sidebar({ activePage, onNavigate, user }) {
  const initials = user?.name
    ? user.name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase()
    : "WL";

  return (
    <aside style={S.aside}>
      {/* Logo */}
      <div style={S.logoBlock}>
        <div style={S.logoIcon}>
          <Icon name="leaf" size={18} />
        </div>
        <div>
          <div style={S.logoText}>WasteLink</div>
          <div style={S.logoSub}>RECYCLING MARKETPLACE</div>
        </div>
      </div>

      {/* Nav */}
      <nav style={S.nav}>
        <div style={S.sectionLabel}>Main Menu</div>
        {NAV_ITEMS.map((item) => {
          const active = activePage === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              style={{ ...S.navItem, ...(active ? S.navItemActive : {}) }}
              onMouseEnter={(e) => { if (!active) Object.assign(e.currentTarget.style, S.navItemHover); }}
              onMouseLeave={(e) => { if (!active) Object.assign(e.currentTarget.style, S.navItemLeave); }}
            >
              <span style={{ ...S.iconWrap, ...(active ? S.iconWrapActive : {}) }}>
                <Icon name={item.icon} size={15} />
              </span>
              <span style={S.navLabel}>{item.label}</span>
              {item.badge && <span style={S.badge}>{item.badge}</span>}
              {active && <span style={S.activeBar} />}
            </button>
          );
        })}
      </nav>

      {/* User footer */}
      <div style={S.userFooter}>
        <div style={S.avatar}>{initials}</div>
        <div style={S.userInfo}>
          <div style={S.userName}>{user?.name || "Guest"}</div>
          <span style={{ ...S.roleBadge, ...(user?.role === "recycler" ? S.roleRecycler : S.roleSeller) }}>
            {user?.role || "seller"}
          </span>
        </div>
      </div>
    </aside>
  );
}

